def assemble_context(task, environment, history):
    # 只保留与当前任务相关的片段，其余压缩或丢弃
    relevant = retrieve(environment, query=task)
    return {
        'system': '你是执行任务的 Agent',
        'user': task,
        'context': relevant,
        'history': history[-N:],  # 只带最近 N 轮，控制 token
    }

import json

def execute_tool(name, raw_input):
    try:
        args = json.loads(raw_input)  # 解析安全，不用字符串匹配
    except json.JSONDecodeError:
        return {'tool_use_id': None, 'content': '参数不是合法 JSON', 'is_error': True}
    fn = TOOL_REGISTRY.get(name)
    if fn is None:
        return {'tool_use_id': None, 'content': f'工具 {name} 不存在', 'is_error': True}
    return fn(**args)
